export default function WorkspaceInspector({
  workspaceId,
  transport,
  refreshKey,
  view = "combined",
  active = true,
  className = "",
  style,
}: WorkspaceInspectorProps) {
  const [tab, setTab] = useState<InspectorTab>("files");
  const [files, setFiles] = useState<WorkspaceFileNode[]>([]);
  const [changes, setChanges] = useState<WorkspaceChangedFile[]>([]);
  const [selectedPath, setSelectedPath] = useState<string | null>(null);
  const [viewerMode, setViewerMode] = useState<ViewerMode>("preview");
  const [terminalHeight, setTerminalHeight] = useState(storedTerminalHeight);
  const [error, setError] = useState<string | null>(null);

  const refresh = useCallback(async () => {
    if (!active || view === "terminal") return;
    try {
      const [treeResponse, changedResponse] = await Promise.all([
        transport.get<{ files: WorkspaceFileNode[] }>(
          `/api/workspaces/${workspaceId}/files/tree`,
        ),
        transport.get<{ files: WorkspaceChangedFile[] }>(
          `/api/workspaces/${workspaceId}/files/changed`,
        ),
      ]);
      setFiles(treeResponse.files);
      setChanges(changedResponse.files);
      setError(null);
    } catch (apiError) {
      setError(
        apiError instanceof Error
          ? apiError.message
          : "Failed to load workspace files",
      );
    }
  }, [active, transport, view, workspaceId]);

  const refreshChanges = useCallback(async () => {
    if (!active || view === "terminal") return;
    try {
      const changedResponse = await transport.get<{
        files: WorkspaceChangedFile[];
      }>(`/api/workspaces/${workspaceId}/files/changed`);
      setChanges(changedResponse.files);
      setError(null);
    } catch (apiError) {
      setError(
        apiError instanceof Error
          ? apiError.message
          : "Failed to load workspace changes",
      );
    }
  }, [active, transport, view, workspaceId]);

  useEffect(() => {
    void refresh();
  }, [refresh, refreshKey]);

  useEffect(() => {
    if (!active || view === "terminal") return;
    const interval = window.setInterval(() => {
      if (document.visibilityState === "visible") {
        void refreshChanges();
      }
    }, FILE_STATUS_REFRESH_MS);
    const onFocus = () => void refresh();
    window.addEventListener("focus", onFocus);
    return () => {
      window.clearInterval(interval);
      window.removeEventListener("focus", onFocus);
    };
  }, [active, refresh, refreshChanges, view]);

  const beginTerminalResize = useCallback(
    (event: ReactPointerEvent<HTMLDivElement>) => {
      event.currentTarget.setPointerCapture(event.pointerId);
      const startY = event.clientY;
      const startHeight = terminalHeight;
      const onMove = (moveEvent: PointerEvent) => {
        const nextHeight = Math.min(
          TERMINAL_HEIGHT_MAX,
          Math.max(
            TERMINAL_HEIGHT_MIN,
            startHeight - (moveEvent.clientY - startY),
          ),
        );
        setTerminalHeight(nextHeight);
        sessionStorage.setItem("yinshi-terminal-height", String(nextHeight));
      };
      const onUp = () => {
        window.removeEventListener("pointermove", onMove);
        window.removeEventListener("pointerup", onUp);
      };
      window.addEventListener("pointermove", onMove);
      window.addEventListener("pointerup", onUp);
    },
    [terminalHeight],
  );

  return (
    <aside
      aria-label={
        view === "files"
          ? "Workspace files"
          : view === "terminal"
            ? "Workspace terminal"
            : "Workspace inspector"
      }
      style={style}
      className={`flex min-h-0 flex-col border-l border-gray-800 bg-gray-900 ${className}`}
    >
      {view === "terminal" ? (
        <div className="min-h-0 flex-1">
          <RuntimeTerminalPane
            workspaceId={workspaceId}
            transport={transport}
            active={active}
          />
        </div>
      ) : (
        <>
          <div className="flex items-center border-b border-gray-800 px-3 py-2">
            <button
              type="button"
              onClick={() => setTab("files")}
              className={`rounded px-2 py-1 text-xs font-medium ${tab === "files" ? "bg-gray-800 text-gray-100" : "text-gray-500 hover:text-gray-200"}`}
            >
              All files <span className="text-gray-500">{countFiles(files)}</span>
            </button>
            <button
              type="button"
              onClick={() => setTab("changes")}
              className={`ml-1 rounded px-2 py-1 text-xs font-medium ${tab === "changes" ? "bg-gray-800 text-gray-100" : "text-gray-500 hover:text-gray-200"}`}
            >
              Changes <span className="text-gray-500">{changes.length}</span>
            </button>
            <button
              type="button"
              onClick={() => void refresh()}
              className="ml-auto rounded px-2 py-1 text-[11px] text-gray-500 hover:bg-gray-800 hover:text-gray-200"
            >
              Refresh
            </button>
          </div>

          {error && (
            <div className="border-b border-red-900/40 bg-red-950/40 px-3 py-2 text-xs text-red-200">
              {error}
            </div>
          )}

          <div className="flex min-h-0 flex-1 flex-col">
            <div className="min-h-0 flex-1 overflow-auto p-2">
              {tab === "files" ? (
                files.length ? (
                  <FileTree
                    nodes={files}
                    selectedPath={selectedPath}
                    onSelect={(path) => {
                      setSelectedPath(path);
                      setViewerMode("preview");
                    }}
                  />
                ) : (
                  <div className="p-3 text-xs text-gray-500">
                    No visible files.
                  </div>
                )
              ) : changes.length ? (
                <div className="space-y-1">
                  {changes.map((file) => (
                    <button
                      key={`${file.status}-${file.path}`}
                      type="button"
                      onClick={() => {
                        setSelectedPath(file.path);
                        setViewerMode("diff");
                      }}
                      className={`flex w-full items-center gap-2 rounded px-2 py-1 text-left text-xs ${
                        selectedPath === file.path
                          ? "bg-blue-500/15 text-blue-200"
                          : "text-gray-300 hover:bg-gray-800 hover:text-gray-100"
                      }`}
                      title={file.path}
                    >
                      <span className="w-5 shrink-0 rounded bg-gray-800 px-1 text-center font-mono text-[10px] text-gray-400">
                        {statusLabel(file)}
                      </span>
                      <span className="truncate">{file.path}</span>
                    </button>
                  ))}
                </div>
              ) : (
                <div className="p-3 text-xs text-gray-500">
                  No uncommitted changes.
                </div>
              )}
            </div>
            <div className="h-[42%] min-h-[180px] max-h-[50%]">
              <FileViewer
                workspaceId={workspaceId}
                transport={transport}
                path={selectedPath}
                mode={viewerMode}
                onModeChange={setViewerMode}
                onSaved={() => void refresh()}
              />
            </div>
          </div>

          {view === "combined" && (
            <>
              <div
                role="separator"
                aria-label="Resize terminal"
                onPointerDown={beginTerminalResize}
                className="h-1.5 cursor-row-resize border-y border-gray-800 bg-gray-800/80 hover:bg-blue-500/40"
              />
              <div style={{ height: terminalHeight }} className="shrink-0">
                <RuntimeTerminalPane
                  workspaceId={workspaceId}
                  transport={transport}
                  active={active}
                />
              </div>
            </>
          )}
        </>
      )}
    </aside>
  );
}

/* Covers public landing navigation and the authenticated mobile drawer through Playwright. */
import { expect, test } from "@playwright/test";

import {
  authenticateContext,
  createLocalRepo,
  seedFullStack,
  uniqueEmail,
} from "./helpers/testApp";

test("landing renders and targets configured login", async ({ page }) => {
  await page.goto("/");

  await expect(
    page.getByRole("heading", {
      name: "Run coding agents against your repositories from any browser.",
    }),
  ).toBeVisible();
  await expect(page.getByRole("link", { name: "Sign in" })).toHaveAttribute(
    "href",
    "/auth/login",
  );
});

test("mobile navigation toggles the authenticated sidebar", async ({ page }) => {
  await page.setViewportSize({ width: 390, height: 844 });
  await authenticateContext(page.context());

  await page.goto("/app");

  const overlay = page.getByTestId("sidebar-overlay");
  await expect(overlay).toHaveCount(0);

  await page.getByLabel("Toggle sidebar").click();
  await expect(overlay).toBeVisible();

  await overlay.click();
  await expect(overlay).toHaveCount(0);
});

test("mobile Settings title clears the sidebar toggle", async ({ page }) => {
  await page.setViewportSize({ width: 390, height: 844 });
  await authenticateContext(page.context());

  await page.goto("/app/settings");

  const toggleBox = await page.getByLabel("Toggle sidebar").boundingBox();
  const titleBox = await page
    .getByRole("heading", { name: "Settings", level: 1 })
    .boundingBox();

  expect(toggleBox).not.toBeNull();
  expect(titleBox).not.toBeNull();
  expect(titleBox!.y).toBeGreaterThanOrEqual(toggleBox!.y + toggleBox!.height);
});

test("mobile workspace controls render and switch panels", async ({ page }) => {
  await page.setViewportSize({ width: 390, height: 844 });

  const email = uniqueEmail("workspace-controls");
  const authSession = await authenticateContext(page.context(), email);
  const repoPath = createLocalRepo("workspace-controls");
  const seeded = await seedFullStack(authSession, repoPath);

  await page.goto(`/app/session/${seeded.session.id}`);

